  await page.evaluate(()=>{const k='aiShogiTournament21540',s=JSON.parse(localStorage.getItem(k)),a=s.active;a.status='active';a.bossChallenge.status='locked';a.round=1;a.playerSlot=0;a.pending='next';a.lastOpponent=null;a.bracket.rounds[1][0]='__PLAYER__';a.bracket.rounds[1][1]=null;for(const m of Object.values(a.bracket.matches||{}))if(m.status==='running')m.dueAt=Date.now()+600000;localStorage.setItem(k,JSON.stringify(s));window.AI_SHOGI_TOURNAMENT.render();window.AI_SHOGI_TOURNAMENT_GAME_UI.render()});
