  await page.waitForFunction(()=>{const a=window.AI_SHOGI_TOURNAMENT_GAME_UI?.audit?.();return a?.matchupCard&&a?.matchupWaiting===false&&a?.matchupOpponent==='あやなみ'&&a?.matchupPortraitCatalogMatch===true&&a?.matchupOverflow===0},{timeout:5000});
