  assert.equal(resolvedMatch.matchupWaiting,false);assert.equal(resolvedMatch.matchupOpponent,'あやなみ');assert.equal(resolvedMatch.matchupPortrait,true);assert.equal(resolvedMatch.matchupPortraitCatalogMatch,true);assert.equal(resolvedMatch.matchupOpponentRating,1800);assert.equal(resolvedMatch.matchupOverflow,0);assert.equal(resolvedMatch.connectors,30);assert.equal(resolvedMatch.roster,26);assert.equal(resolvedMatch.docOverflow,0);

