  await page.waitForFunction(()=>{const a=window.AI_SHOGI_TOURNAMENT_GAME_UI?.audit?.();return a?.progressValue==='EX'&&a?.progressLabel==='杯ボス解放'&&a?.matchupOpponent==='しんじ'&&a?.matchupBoss===true&&a?.matchupPortraitCatalogMatch===true},{timeout:5000});
